window.HOEREN_TESTS[24] = {"id":"bibliothek-und-lesen","name":"Bibliothek und Lesen","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Bibliotheksbesucher, eine Information für Sie: Wir sind ab Montag bis 22 Uhr offen, statt bis 20 Uhr. Mehr Zeit für Sie zum Lesen oder Studieren. Am Wochenende bleiben die Zeiten gleich: Samstag bis 18 Uhr, Sonntag geschlossen. Bitte beachten Sie die längeren Öffnungszeiten unter der Woche. Danke!","gender":"f","q":"Wann ist die neue Schließzeit unter der Woche?","opts":["22 Uhr.","20 Uhr.","18 Uhr."],"correct":0},{"transcript":"Hallo Frau Wagner, hier ist die Stadtbibliothek. Das Buch, das Sie vorbestellt haben — ‚Der Steppenwolf‘ von Hermann Hesse — ist eingetroffen. Bitte holen Sie es innerhalb von 7 Tagen ab. Nicht 3 Tage und kein Monat, genau 7 Tage. Danach wird es dem nächsten Interessenten gegeben. Wir haben aktuell 5 weitere Personen, die darauf warten. Danke!","gender":"m","q":"Wie lange hat Frau Wagner Zeit zur Abholung?","opts":["3 Tage.","Einen Monat.","7 Tage."],"correct":2},{"transcript":"Hi Tom, hier ist Lisa. Ich habe das Buch zurückgegeben, das ich von dir geliehen hatte — ‚1984‘ von Orwell. Es war wirklich super! Jetzt möchte ich gern ‚Schöne neue Welt‘ lesen. Hast du das auch in deiner Sammlung? Wenn ja, kann ich vorbeikommen am Wochenende, falls du Zeit hast.","gender":"f","q":"Was möchte Lisa lesen?","opts":["‚Schöne neue Welt‘.","‚1984‘ nochmal.","Ein Krimi."],"correct":0},{"transcript":"Liebe Mitglieder der Buchclub-Gruppe, das nächste Treffen am 15. März wird in einem Café statt in der Bibliothek stattfinden. Im Café Buchstabe, Königstraße 12, ab 19 Uhr. Wir besprechen das neue Buch ‚Drei‘ von Dror Mishani. Wer das Buch noch nicht gelesen hat — bitte vorher beenden. Danke!","gender":"m","q":"Wo findet das Treffen statt?","opts":["In der Bibliothek wie üblich.","Bei einem Mitglied zu Hause.","Im Café Buchstabe."],"correct":2},{"transcript":"Achtung an alle Bibliotheksbenutzer: Ab Mai gibt es eine Neuerung. Jeder kann jetzt 10 Bücher gleichzeitig leihen, statt 5 wie früher. Die Leihfrist bleibt 4 Wochen. Für Magazine und CDs bleibt alles wie bisher — diese können nur 2 Wochen geliehen werden. Wir hoffen, das macht das Leben unserer Leser einfacher.","gender":"f","q":"Wie viele Bücher kann man jetzt gleichzeitig leihen?","opts":["5 wie früher.","10.","2."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Was liest welche Person? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Katrin","gender":"f","text":"Hallo Martin! Die Bibliothek bringt heute eine große Kiste. Jeder sucht sich etwas zum Lesen aus."},{"speaker":"Martin","gender":"m","text":"Ich habe die Wünsche schon aufgeschrieben. Die Kiste steht seit dem Morgen im Flur."},{"speaker":"Katrin","gender":"f","text":"Ich lese am liebsten Krimis. Abends mag ich spannende Fälle."},{"speaker":"Martin","gender":"m","text":"Krimis passen gut zu dir, Katrin. Möchte jemand von uns Gedichte?"},{"speaker":"Katrin","gender":"f","text":"Nein. Gedichte nehmen wir nicht mit. Die kurzen Zeilen bleiben in der Kiste."},{"speaker":"Martin","gender":"m","text":"Ich bleibe gern bei der Vergangenheit."},{"speaker":"Katrin","gender":"f","text":"Du liest Geschichtsbücher und Biografien, Martin. Du magst echte Lebensgeschichten sehr."},{"speaker":"Martin","gender":"m","text":"Die Biografien liegen oben in der Kiste. Lisa will etwas Schönes zum Träumen."},{"speaker":"Katrin","gender":"f","text":"Lisa liest Liebesromane. Sie mag Geschichten mit einem richtig guten Ende."},{"speaker":"Martin","gender":"m","text":"Liebesromane nimmt sie gern zwei Stück mit. Tom sucht Abenteuer weit weg von der Erde."},{"speaker":"Katrin","gender":"f","text":"Tom liest Science-Fiction. Raketen und ferne Planeten findet er besonders stark."},{"speaker":"Martin","gender":"m","text":"Die Science-Fiction liegt ganz unten. Liegen in der Kiste auch Kochbücher für neue Rezepte?"},{"speaker":"Katrin","gender":"f","text":"Kochbücher brauchen wir nicht. Wir kochen schon ohne Rezepte aus einem Buch."},{"speaker":"Martin","gender":"m","text":"Marie ist noch klein und braucht Bilder. Märchen liest du ihr manchmal abends vor."},{"speaker":"Katrin","gender":"f","text":"Marie liest Kinderbücher und Märchen. Die bunten Bilder helfen ihr beim Verstehen."},{"speaker":"Martin","gender":"m","text":"Einverstanden. Ich trage die Bücher morgen in die Bibliothek zurück. Bis heute Abend."}],"options":[{"letter":"a","text":"Kinderbücher und Märchen"},{"letter":"b","text":"Gedichte"},{"letter":"c","text":"Science-Fiction"},{"letter":"d","text":"Reiseberichte"},{"letter":"e","text":"Liebesromane"},{"letter":"f","text":"Geschichtsbücher und Biografien"},{"letter":"g","text":"Kochbücher"},{"letter":"h","text":"Comics und Manga"},{"letter":"i","text":"Krimis"}],"items":[{"person":"Katrin","correct":"i"},{"person":"Martin","correct":"f"},{"person":"Lisa","correct":"e"},{"person":"Tom","correct":"c"},{"person":"Marie","correct":"a"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Bibliothekarin","gender":"f","text":"Guten Tag, möchten Sie sich anmelden? Erwachsene, Studenten oder Kinder?"},{"speaker":"Kunde","gender":"m","text":"Ja, was kostet das? 25 Euro habe ich gehört, oder ist es kostenlos?"},{"speaker":"Bibliothekarin","gender":"f","text":"Erwachsene 25 Euro pro Jahr, Studenten 12 Euro, Kinder kostenlos. Ausweis bitte mitbringen."},{"speaker":"Kunde","gender":"m","text":"Ich bin Student, nicht Kind und nicht normaler Erwachsener. Dann 12 Euro."},{"speaker":"Bibliothekarin","gender":"f","text":"Dann 12 Euro. Bitte den Ausweis, ich mache den Ausweis für die Bibliothek."}],"q":"Wie viel zahlt der Kunde?","opts":["25 Euro.","12 Euro.","Kostenlos."],"correct":1},{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, können Sie mir ein gutes Buch empfehlen? Ich suche etwas für den Abend."},{"speaker":"Buchhändler","gender":"m","text":"Was lesen Sie gern? Krimi, Roman, Sachbuch? Wir haben von allem."},{"speaker":"Kundin","gender":"f","text":"Eigentlich Romane. Etwas Leichtes, ich hatte eine schwere Woche. Kein Krimi und kein Sachbuch heute."},{"speaker":"Buchhändler","gender":"m","text":"Dann empfehle ich Ihnen ‚Sommer in Italien‘ — eine warmherzige Familiengeschichte, kein Krimi."},{"speaker":"Kundin","gender":"f","text":"Das klingt gut, danke! Ich nehme ‚Sommer in Italien‘, nicht das Sachbuch."}],"q":"Welches Buch wird empfohlen?","opts":["‚Sommer in Italien‘.","Ein Krimi.","Ein Sachbuch."],"correct":0},{"lines":[{"speaker":"Mutter","gender":"f","text":"Welches Buch lesen wir heute Abend? Den Kleinen Prinzen, etwas Neues, oder gar nichts weil es spät ist?"},{"speaker":"Sohn","gender":"m","text":"Den ‚Kleinen Prinzen‘! Leer ausgehen will ich nicht, ich will eine Geschichte."},{"speaker":"Mutter","gender":"f","text":"Wir haben das schon dreimal gelesen. Vielleicht etwas Neues?"},{"speaker":"Sohn","gender":"m","text":"Aber ich liebe ihn. Bitte, Mama, nicht das neue Buch."},{"speaker":"Mutter","gender":"f","text":"Okay, dann nochmal den Kleinen Prinzen. Morgen nehmen wir etwas Neues."}],"q":"Was wird vorgelesen?","opts":["‚Der kleine Prinz‘.","Ein neues Buch.","Nichts."],"correct":0},{"lines":[{"speaker":"Mitarbeiter","gender":"m","text":"Guten Tag, Sie möchten dieses Buch verlängern? Oder zurückgeben?"},{"speaker":"Leserin","gender":"f","text":"Ja, ich bin noch nicht fertig. Behalten ohne Verlängerung geht nicht, oder?"},{"speaker":"Mitarbeiter","gender":"m","text":"Verlängerung um 2 Wochen ist möglich. Aber dieses Buch ist vorgemerkt — ein anderer wartet darauf. Einfach behalten ohne Verlängerung geht nicht."},{"speaker":"Leserin","gender":"f","text":"Oh. Dann gebe ich es lieber zurück. Ich kann es später nochmal leihen, nicht verlängern."},{"speaker":"Mitarbeiter","gender":"m","text":"Danke, das ist fair. Ich notiere die Rückgabe."}],"q":"Was macht die Leserin?","opts":["Verlängert das Buch.","Behält es ohne Verlängerung.","Gibt es zurück."],"correct":2},{"lines":[{"speaker":"Sohn","gender":"m","text":"Mama, ich muss ein Buchreferat machen. Tom Sawyer, Robinson Crusoe oder Harry Potter — was meinst du?"},{"speaker":"Mutter","gender":"f","text":"Welches Buch liegt dir mehr? Harry Potter kennen alle, Robinson ist lang."},{"speaker":"Sohn","gender":"m","text":"Wir können wählen. Ich denke an ‚Tom Sawyer‘, nicht Harry Potter und nicht Robinson Crusoe."},{"speaker":"Mutter","gender":"f","text":"Schöne Wahl. Klassik. Du wirst Tom Sawyer lieben, das ist spannend und nicht zu lang."},{"speaker":"Sohn","gender":"m","text":"Super, dann Tom Sawyer. Ich fange heute an zu lesen."}],"q":"Über welches Buch macht der Sohn Referat?","opts":["‚Robinson Crusoe‘.","‚Tom Sawyer‘.","‚Harry Potter‘."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Klaus, einem Bibliothekar. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Herr Klaus, Sie sind seit 28 Jahren Bibliothekar in der Stadtbibliothek. Wie hat sich Ihr Beruf in dieser Zeit verändert?"},{"speaker":"Klaus","gender":"m","text":"Sehr stark. Vor 28 Jahren waren wir nur ein Bücher-Verleih. Heute sind wir viel mehr: Computer-Arbeitsplätze, Veranstaltungen, Sprachkurse, sogar Maker-Spaces mit 3D-Druckern. Die Bibliothek ist ein Gemeinschaftsort geworden."},{"speaker":"Reporter","gender":"m","text":"Lesen die Menschen heute weniger?"},{"speaker":"Klaus","gender":"m","text":"Das ist eine gute Frage. Junge Leute lesen anders — viel mehr digital, weniger gedruckte Bücher. Aber wir haben mehr Leser als vor 10 Jahren! E-Books bei uns sind sehr beliebt geworden."},{"speaker":"Reporter","gender":"m","text":"Welche Bücher werden am meisten ausgeliehen?"},{"speaker":"Klaus","gender":"m","text":"Krimis sind die Nummer eins, schon immer. Dann Liebesromane. Sachbücher zum Beispiel über Kochen oder Reisen. Klassische Literatur weniger — die wird mehr in der Schule gelesen, nicht freiwillig."},{"speaker":"Reporter","gender":"m","text":"Welche Veranstaltungen organisieren Sie?"},{"speaker":"Klaus","gender":"m","text":"Lesungen mit Autoren, Buchclub, Vorlesen für Kinder am Samstag. Manchmal Sprach-Tandems, wo sich Menschen aus verschiedenen Ländern treffen. Wir wollen, dass die Bibliothek lebt."},{"speaker":"Reporter","gender":"m","text":"Lesen Sie selbst viel?"},{"speaker":"Klaus","gender":"m","text":"Privat sehr wenig, ehrlich gesagt. Ich bin den ganzen Tag mit Büchern beschäftigt — Auswählen, Katalogisieren, Bestellen. Zu Hause möchte ich Pause vom Lesen. Ich höre lieber Musik oder schaue Filme."}],"items":[{"q":"Heute hat die Bibliothek mehr Leser als vor 10 Jahren.","correct":"ja"},{"q":"Vor 28 Jahren war die Bibliothek mehr als nur ein Bücher-Verleih.","correct":"nein"},{"q":"Klassische Literatur wird heute am meisten freiwillig gelesen.","correct":"nein"},{"q":"Die Bibliothek organisiert auch Veranstaltungen für Kinder.","correct":"ja"},{"q":"Herr Klaus liest privat sehr viele Bücher.","correct":"nein"}]}]};
